import{damageTypes,spellEffectCatalog,featureEffectCatalog}from"../data/effects.js";
import{finalScores,mod}from"../selectors.js";

function diceStats(text){const normalized=String(text||"").replace(/×/g,"x");const simple=normalized.match(/^(\d+)d(\d+)(?:\s*\+\s*(\d+))?$/i);if(simple){const n=Number(simple[1]),s=Number(simple[2]),b=Number(simple[3]||0);return{min:n+b,avg:n*(s+1)/2+b,max:n*s+b}}const multi=normalized.match(/^(\d+)\s*x\s*\((\d+)d(\d+)\s*\+\s*(\d+)\)$/i);if(multi){const c=Number(multi[1]),n=Number(multi[2]),s=Number(multi[3]),b=Number(multi[4]);return{min:c*(n+b),avg:c*(n*(s+1)/2+b),max:c*(n*s+b)}}return null}
function addDice(base,extra,count){const a=String(base).match(/^(\d+)d(\d+)$/i),b=String(extra).match(/^(\d+)d(\d+)$/i);if(!a||!b||a[2]!==b[2])return base;return`${Number(a[1])+Number(b[1])*count}d${a[2]}`}
function scaledDice(part,level){let dice=part.dice;if(part.scaling){for(const threshold of Object.keys(part.scaling).map(Number).sort((a,b)=>a-b))if(level>=threshold)dice=part.scaling[threshold]}return dice}
function hasChoice(build,groupId,key){return(build.classChoices?.[groupId]||[]).includes(key)}
function modifierValue(build,source,mode){const scores=finalScores(build);if(mode==="spellcasting")return source?mod(scores[source.ability]):0;if(mode==="str")return mod(scores.str);if(mode==="dex")return mod(scores.dex);if(mode==="weaponAbility")return Math.max(mod(scores.str),mod(scores.dex));if(mode==="eldritch")return hasChoice(build,"warlock-invocations","agonizing")?mod(scores.cha):0;return 0}
function formulaWithModifier(dice,value){if(!value||String(dice).includes("武器伤害"))return String(dice);if(String(dice).includes("×")||String(dice).includes("x"))return`${dice}${value>0?` + ${value}`:` − ${Math.abs(value)}`}`;return`${dice}${value>0?` + ${value}`:` − ${Math.abs(value)}`}`}
function castLevelDice(part,spell,castLevel){if(!part.upcastDice||castLevel<=spell.level)return scaledDice(part,12);const step=part.upcastStep||1,count=Math.floor((castLevel-spell.level)/step);return addDice(part.dice,part.upcastDice,count)}
export function spellEffectSummary(build,spell,source,castLevel=spell.level){const effect=spellEffectCatalog[spell.key];if(!effect)return null;const characterLevel=build.targetLevel;const parts=effect.parts.map(part=>{let dice=scaledDice(part,characterLevel);if(part.upcastDice&&castLevel>spell.level)dice=castLevelDice(part,spell,castLevel);if(part.flatPerCastLevel)dice=String(part.flatPerCastLevel*Math.max(1,castLevel));else if(part.flat!==undefined)dice=String(part.flat+(part.upcastFlat||0)*Math.max(0,castLevel-spell.level));const modifier=modifierValue(build,source,part.modifier),beams=part.beams?Object.keys(part.beams).map(Number).sort((a,b)=>a-b).reduce((n,t)=>characterLevel>=t?part.beams[t]:n,1):1;let formula=formulaWithModifier(dice,modifier);if(beams>1)formula=`${beams} × (${formula})`;const stats=diceStats(formula);return{...part,dice,formula,modifier,beams,stats,typeInfo:damageTypes[part.type]||damageTypes.force}});return{...effect,parts,castLevel,note:effect.note||""}}
export function featureEffectSummary(build,group,optionKey){const data=featureEffectCatalog[optionKey]||null;if(!data)return null;const source={ability:group.classKey==="warlock"?"cha":group.classKey==="ranger"?"wis":"str"};const modifier=modifierValue(build,source,data.modifier);let formula=data.dice||"";if(formula&&modifier)formula=formulaWithModifier(formula,modifier);else if(!formula&&data.modifier&&modifier)formula=modifier>0?`+${modifier}`:String(modifier);return{...data,formula,modifier,typeInfo:data.type?damageTypes[data.type]:data.resistance?damageTypes[data.resistance]:null}}
export function damageTypeInfo(type){return damageTypes[type]||damageTypes.force}
export function effectAverageLabel(stats){if(!stats)return"";const avg=Number.isInteger(stats.avg)?String(stats.avg):stats.avg.toFixed(1);return`最低 ${stats.min} · 平均 ${avg} · 最高 ${stats.max}`}
